function validate([arr1, arr2, arr3]) {
  for (const [name, arr] of [['arr1', arr1], ['arr2', arr2], ['arr3', arr3]]) {
    if (arr.length < 1 || arr.length > 1000) return `${name} needs 1 to 1000 values.`;
    for (let i = 0; i < arr.length; i++) {
      if (!Number.isInteger(arr[i]) || arr[i] < 1 || arr[i] > 2000) return `Each value of ${name} is an integer from 1 to 2000.`;
      if (i > 0 && arr[i] <= arr[i - 1]) return `${name} must be strictly increasing.`;
    }
  }
  return null;
}

