function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Picks `count` distinct values from 1..top and returns them in increasing order.
  const pick = (count, top) => {
    const chosen = [];
    let left = count;
    for (let v = 1; v <= top && left > 0; v++) {
      if (rand() * (top - v + 1) < left) { chosen.push(v); left--; }
    }
    return chosen;
  };
  if (size === 'small') {
    const top = int(1, 12);
    return [pick(int(1, Math.min(6, top)), top), pick(int(1, Math.min(6, top)), top), pick(int(1, Math.min(6, top)), top)];
  }
  return [pick(int(600, 1000), 2000), pick(int(600, 1000), 2000), pick(int(600, 1000), 2000)];
}
